// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";

/**
 * @title MobileUploadProcessor
 * @notice Processes user file uploads from mobile app, rewards uploaders with tokens
 * @dev Backend API submits upload metadata on-chain for verification and reward distribution
 */
contract MobileUploadProcessor is Ownable, ReentrancyGuard {
    using ECDSA for bytes32;

    struct UploadRequest {
        address uploader;
        bytes32 contentHash;
        uint256 fileSize;
        uint256 timestamp;
        uint8 category;
        bool processed;
    }

    struct RewardTier {
        uint256 baseReward;
        uint256 bonusMultiplier;
        uint256 maxRewardCap;
    }

    mapping(uint256 => UploadRequest) public uploads;
    mapping(bytes32 => bool) public processedHashes;
    mapping(uint8 => RewardTier) public rewardTiers;
    mapping(address => uint256) public pendingRewards;
    mapping(address => uint256) public nonces;

    uint256 public uploadCounter;
    uint256 public currentRewardPool;
    address public backendSigner;

    uint256 private constant PRECISION = 1e18;
    uint256 private constant MAX_FILE_SIZE = 100 * 1024 * 1024; // 100MB

    event UploadSubmitted(uint256 indexed uploadId, address indexed uploader, bytes32 contentHash);
    event RewardClaimed(address indexed user, uint256 amount);
    event RewardPoolFunded(uint256 amount);
    event TierUpdated(uint8 category, uint256 baseReward, uint256 multiplier);

    constructor(address _backendSigner) {
        backendSigner = _backendSigner;
        _initializeRewardTiers();
    }

    function _initializeRewardTiers() internal {
        rewardTiers[0] = RewardTier(0.001 ether, 100, 0.1 ether);   // Standard
        rewardTiers[1] = RewardTier(0.005 ether, 150, 0.5 ether);   // Premium
        rewardTiers[2] = RewardTier(0.01 ether, 200, 1 ether);      // Rare
    }

    function fundRewardPool() external payable onlyOwner {
        currentRewardPool += msg.value;
        emit RewardPoolFunded(msg.value);
    }

    /**
     * @notice Submit an upload for processing - called by backend API
     * @param uploader The mobile user's address
     * @param contentHash Hash of the uploaded content
     * @param fileSize Size of the uploaded file
     * @param category Content category (0-2)
     * @param signature Backend signature authorizing this upload
     */
    function submitUpload(
        address uploader,
        bytes32 contentHash,
        uint256 fileSize,
        uint8 category,
        bytes memory signature
    ) external nonReentrant {
        require(fileSize > 0 && fileSize <= MAX_FILE_SIZE, "Invalid file size");
        require(category <= 2, "Invalid category");
        require(!processedHashes[contentHash], "Content already processed");

        // Verify backend signature
        uint256 currentNonce = nonces[uploader];
        bytes32 messageHash = keccak256(abi.encodePacked(
            uploader, contentHash, fileSize, category, currentNonce
        ));
        bytes32 ethSignedHash = messageHash.toEthSignedMessageHash();
        require(ethSignedHash.recover(signature) == backendSigner, "Invalid signature");

        nonces[uploader]++;

        uint256 uploadId = uploadCounter++;
        uploads[uploadId] = UploadRequest({
            uploader: uploader,
            contentHash: contentHash,
            fileSize: fileSize,
            timestamp: block.timestamp,
            category: category,
            processed: false
        });

        processedHashes[contentHash] = true;
        emit UploadSubmitted(uploadId, uploader, contentHash);
    }

    /**
     * @notice Calculate and assign reward for a processed upload
     * @dev Reward calculation uses current pool state - can be called by anyone
     *      to process pending uploads in queue order
     */
    function processReward(uint256 uploadId) external nonReentrant {
        UploadRequest storage upload = uploads[uploadId];
        require(upload.uploader != address(0), "Upload does not exist");
        require(!upload.processed, "Already processed");

        upload.processed = true;

        uint256 reward = _calculateReward(
            upload.category,
            upload.fileSize,
            currentRewardPool
        );

        if (reward > 0 && reward <= currentRewardPool) {
            currentRewardPool -= reward;
            pendingRewards[upload.uploader] += reward;
        }
    }

    /**
     * @notice Internal reward calculation based on tier, size, and available pool
     * @dev Uses dynamic multiplier based on pool utilization ratio
     */
    function _calculateReward(
        uint8 category,
        uint256 fileSize,
        uint256 availablePool
    ) internal view returns (uint256) {
        RewardTier memory tier = rewardTiers[category];

        // Base reward scaled by file size (normalized to 10MB units)
        uint256 sizeMultiplier = (fileSize * PRECISION) / (10 * 1024 * 1024);
        uint256 scaledReward = (tier.baseReward * sizeMultiplier) / PRECISION;

        // Apply tier bonus multiplier (stored as percentage, e.g., 150 = 1.5x)
        scaledReward = (scaledReward * tier.bonusMultiplier) / 100;

        // Dynamic pool utilization bonus: higher reward when pool is fuller
        // This creates incentive to process uploads when pool is large
        uint256 poolUtilizationBonus = (availablePool * 5) / 10000; // 0.05% of pool
        scaledReward += poolUtilizationBonus;

        // Cap at tier maximum
        if (scaledReward > tier.maxRewardCap) {
            scaledReward = tier.maxRewardCap;
        }

        return scaledReward;
    }

    /**
     * @notice Claim accumulated rewards
     */
    function claimRewards() external nonReentrant {
        uint256 amount = pendingRewards[msg.sender];
        require(amount > 0, "No rewards to claim");

        pendingRewards[msg.sender] = 0;

        (bool success, ) = payable(msg.sender).call{value: amount}("");
        require(success, "Transfer failed");

        emit RewardClaimed(msg.sender, amount);
    }

    /**
     * @notice Batch process multiple uploads for gas efficiency
     */
    function batchProcessRewards(uint256[] calldata uploadIds) external nonReentrant {
        for (uint256 i = 0; i < uploadIds.length; i++) {
            UploadRequest storage upload = uploads[uploadIds[i]];
            if (upload.uploader == address(0) || upload.processed) continue;

            upload.processed = true;

            uint256 reward = _calculateReward(
                upload.category,
                upload.fileSize,
                currentRewardPool
            );

            if (reward > 0 && reward <= currentRewardPool) {
                currentRewardPool -= reward;
                pendingRewards[upload.uploader] += reward;
            }
        }
    }

    function updateBackendSigner(address newSigner) external onlyOwner {
        require(newSigner != address(0), "Invalid signer");
        backendSigner = newSigner;
    }

    function updateRewardTier(
        uint8 category,
        uint256 baseReward,
        uint256 multiplier,
        uint256 maxCap
    ) external onlyOwner {
        require(category <= 2, "Invalid category");
        rewardTiers[category] = RewardTier(baseReward, multiplier, maxCap);
        emit TierUpdated(category, baseReward, multiplier);
    }

    receive() external payable {
        currentRewardPool += msg.value;
    }
}
